		t.Run(name, func(t *testing.T) {
			for _, v := range []uint16{VersionTLS10, VersionTLS11, VersionTLS12, VersionTLS13} {
				t.Run(VersionName(v), func(t *testing.T) {
					testLocalCertificateResumption(t, v, useCallback)
				})
			}
		})
	}
